    private static function entry(int $id, string $title, array $aliases, string $franchise, string $hero, string $sourceUrl, array $pairs): array
    {
        $templates = [
            'pl' => 'Jedną z ważnych postaci w tej historii jest {hero}.',
            'en' => 'One important character in this story is {hero}.',
            'de' => 'Eine wichtige Figur in dieser Geschichte heißt {hero}.',
            'fr' => 'Un personnage important dans cette histoire se nomme {hero}.',
            'es' => 'Un personaje importante de esta historia se llama {hero}.',
            'ru' => 'Одного из важных персонажей этой истории зовут {hero}.',
        ];
        $clues = [];
        foreach (array_keys($templates) as $index => $locale) {
            $clues[$locale] = [...$pairs[$index], str_replace('{hero}', $hero, $templates[$locale])];
        }
        return compact('id', 'title', 'aliases', 'franchise', 'clues', 'sourceUrl');
    }
